source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # Find a repeated pair of equal-length colored runs on opposite borders.
    runs = []
    for side, line in (
        ("top", grid[0]), ("bottom", grid[-1]),
        ("left", [row[0] for row in grid]), ("right", [row[-1] for row in grid]),
    ):
        i = 0
        while i < len(line):
            color = line[i]
            j = i + 1
            while j < len(line) and line[j] == color:
                j += 1
            if color != bg and j - i >= 2:
                runs.append((side, color, i, j))
            i = j
    pair = None
    for a in runs:
        for b in runs:
            if a[0] == "top" and b[0] == "bottom" or a[0] == "bottom" and b[0] == "top" or a[0] == "left" and b[0] == "right" or a[0] == "right" and b[0] == "left":
                if a[1] == b[1] and a[3] - a[2] == b[3] - b[2]:
                    pair = (a, b)
                    break
        if pair:
            break
    if pair is None:
        return [row[:] for row in grid]
    a, b = pair
    # Choose the bar whose longitudinal span contains the scattered points.
    bar_color = a[1]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, bar_color)]
    if not markers:
        return [row[:] for row in grid]
    horizontal = a[0] in ("top", "bottom")
    def offset(p, run):
        return (p[1] if horizontal else p[0]) - run[2]
    def aligned(run):
        return sum(0 <= offset(p, run) < run[3]-run[2] for p in markers)
    aligned_run = a if aligned(a) >= aligned(b) else b
    other_run = b if aligned_run is a else a
    direction = {"top": -1, "bottom": 1, "left": -1, "right": 1}[aligned_run[0]]
    out = [row[:] for row in grid]
    dot_color = grid[markers[0][0]][markers[0][1]]
    # Original points cast a ray toward the edge segment they align with.
    for r, c in markers:
        if horizontal:
            rr = r + direction
            while 0 <= rr < h:
                if grid[rr][c] == bar_color:
                    break
                out[rr][c] = dot_color
                rr += direction
        else:
            cc = c + direction
            while 0 <= cc < w:
                if grid[r][cc] == bar_color:
                    break
                out[r][cc] = dot_color
                cc += direction
    # Copy marker offsets onto the opposite bar and project those rays inward.
    offsets = {offset(p, aligned_run) for p in markers if 0 <= offset(p, aligned_run) < aligned_run[3]-aligned_run[2]}
    if horizontal:
        copied_cols = {other_run[2] + off for off in offsets}
        if direction > 0:
            farthest = max(r for r, c in markers)
            # In short, upper-half patterns stop at their furthest marker row.
            end = farthest if farthest <= h // 2 else h - 1
            for c in copied_cols:
                for r in range(1, end + 1):
                    if grid[r][c] != bar_color:
                        out[r][c] = dot_color
        else:
            for c in copied_cols:
                for r in range(h - 2, -1, -1):
                    if grid[r][c] != bar_color:
                        out[r][c] = dot_color
    else:
        copied_rows = {other_run[2] + off for off in offsets}
        if direction > 0:
            for r in copied_rows:
                for c in range(1, w - 1):
                    if grid[r][c] != bar_color:
                        out[r][c] = dot_color
        else:
            for r in copied_rows:
                for c in range(w - 2, 0, -1):
                    if grid[r][c] != bar_color:
                        out[r][c] = dot_color
    for r, c in markers:
        out[r][c] = 4
    return out
'''
